files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #003366;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
}

.nav {
  background: var(--vt-surface);
  box-shadow: 0 1px 10px rgba(0, 0, 0, 0.1);
  padding: 20px 0;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.logo {
  text-decoration: none;
}

.brand {
  color: var(--vt-accent-ink);
  font-size: 24px;
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
}

.brand strong {
  color: var(--vt-ink-soft);
  font-size: 12px;
  display: block;
  font-weight: 600;
}

.navLinks {
  display: flex;
  gap: 2rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  font-weight: 600;
  font-size: 16px;
  padding: 10px 0;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

.hero {
  padding-top: 94px;
  position: relative;
}

.heroSlider {
  position: relative;
  overflow: hidden;
  height: 580px;
  display: flex;
  scroll-snap-type: x mandatory;
  overflow-x: auto;
  scrollbar-width: none;
}

.heroSlider::-webkit-scrollbar {
  display: none;
}

.slide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  position: relative;
}

.slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.heroText h1 {
  font-size: 48px;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 0.5rem;
  color: var(--vt-ink);
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.5rem;
  margin-top: 1rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent-ink);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  position: relative;
  overflow: hidden;
  text-transform: uppercase;
  transition: all 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--vt-line);
  color: var(--vt-accent-ink);
  text-align: center;
  transition: top 300ms cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before,
.customLink:focus-visible::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin: 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

