.section {
  padding: 7rem 0;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2rem;
}

.aboutContent {
  flex: 1 1 50%;
  min-width: 300px;
}

.aboutContent h2 {
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--vt-ink);
}

.aboutContent p {
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  color: var(--vt-ink-soft);
  line-height: 1.7;
  margin-bottom: 1rem;
}

.gallerySection {
  padding: 3rem 0;
  background: var(--vt-surface-2);
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
}

.galleryItem {
  flex: 0 0 50%;
  max-width: 50%;
  overflow: hidden;
}

.galleryItem img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.3s;
}

.galleryItem:hover img {
  transform: scale(1.03);
}

.timelineSection {
  padding: 7rem 0;
  background: var(--vt-surface);
}

.sectionTitle {
  text-align: center;
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 4rem;
  color: var(--vt-ink);
}

.timeline {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.timelineNode {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin: 2rem 0;
}

.timelineNode:nth-child(odd) {
  flex-direction: row;
}

.timelineNode:nth-child(even) {
  flex-direction: row-reverse;
}

.timelineContent {
  width: 42%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  position: relative;
  z-index: 2;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  font-size: 24px;
  font-weight: 600;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
}

.timelineNode:nth-child(odd) .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode:nth-child(even) .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineContent p {
  color: var(--vt-ink-soft);
  padding: 10px 30px;
  margin: 0;
  font-size: 16px;
  font-weight: 300;
  line-height: 1.6;
}

.timelineNode:nth-child(odd) .timelineContent h3,
.timelineNode:nth-child(odd) .timelineContent p {
  text-align: right;
}

.timelineNode:nth-child(even) .timelineContent h3,
.timelineNode:nth-child(even) .timelineContent p {
  text-align: left;
}

.timelineIcon {
  position: relative;
  z-index: 100;
  width: 80px;
  height: 80px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.timelineIcon::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  z-index: 1;
}

.timelineIcon span {
  position: relative;
  z-index: 2;
  color: var(--vt-accent-ink);
  font-size: 32px;
  font-weight: 700;
}

.timelineDate {
  width: 42%;
  padding: 1rem 0;
  font-weight: 600;
  color: var(--vt-ink-soft);
}

.timelineNode:nth-child(odd) .timelineDate {
  text-align: left;
}

.timelineNode:nth-child(even) .timelineDate {
  text-align: right;
}

.price {
  display: block;
  color: var(--vt-accent-ink);
  font-weight: 700;
  margin-top: 0.5rem;
}

.footer {
  background: var(--vt-surface-2);
  padding: 7rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerColHours,
.footerColContact,
.footerColSocial,
.footerColCopyright {
  flex: 1 1 20%;
  min-width: 200px;
}

.footerColHours h5,
.footerColContact h5,
.footerColSocial h5 {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: var(--vt-ink);
}

.footerColHours p,
.footerColContact p,
.footerColCopyright p {
  color: var(--vt-ink-soft);
  font-weight: 300;
  font-size: 16px;
  line-height: 1.6;
  margin-bottom: 0.5rem;
}

.footerColContact a {
  color: var(--vt-accent-ink);
  text-decoration: none;
}

.footerColContact a:hover {
  text-decoration: underline;
}

.socialLinks {
  display: flex;
  gap: 1rem;
}

.socialLinks a {
  color: var(--vt-ink-soft);
  font-size: 20px;
  transition: color 0.3s;
}

.socialLinks a:hover {
  color: var(--vt-accent-ink);
}

.copyright {
  font-size: 14px;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent-ink);
  outline-offset: 2px;
}

@media screen and (min-width: 1600px) {
  .heroSlider {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .nav {
    padding: 10px 0;
  }

  .navLinks {
    gap: 1rem;
  }

  .navLinks a {
    font-size: 14px;
    padding: 5px 0;
  }

  .hero {
    padding-top: 74px;
  }

  .heroSlider {
    height: auto;
    min-height: 400px;
  }

  .heroText {
    position: relative;
    bottom: 100px;
    left: 0;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }

  .heroText h1 {
    font-size: 38px;
  }

  .section {
    padding: 5rem 0;
  }

  .timeline::before {
    top: 60px;
    left: 33px;
    height: 90%;
    transform: none;
  }

  .timelineNode {
    flex-direction: column;
    align-items: flex-start;
    margin: 2rem 0;
    padding-left: 50px;
  }

  .timelineNode:nth-child(even) {
    flex-direction: column;
  }

  .timelineContent,
  .timelineDate {
    width: 100%;
  }

  .timelineIcon {
    position: absolute;
    left: 0;
    top: 60px;
    transform: translateX(-40%);
  }

  .timelineNode:nth-child(odd) .timelineContent h3,
  .timelineNode:nth-child(odd) .timelineContent p,
  .timelineNode:nth-child(even) .timelineContent h3,
  .timelineNode:nth-child(even) .timelineContent p {
    text-align: left;
  }

  .timelineNode:nth-child(odd) .timelineContent h3::after,
  .timelineNode:nth-child(even) .timelineContent h3::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }

  .timelineNode:nth-child(odd) .timelineDate,
  .timelineNode:nth-child(even) .timelineDate {
    text-align: left;
  }

  .footerRow {
    flex-direction: column;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .navIn {
    flex-direction: column;
    align-items: center;
  }

  .navLinks {
    flex-wrap: wrap;
    justify-content: center;
  }

  .galleryItem {
    flex: 0 0 100%;
    max-width: 100%;
  }

  .timeline::before {
    left: 57px;
    height: 87%;
  }

  .timelineIcon {
    left: -10px;
    transform: none;
  }

  .timelineIcon::before {
    width: 70px;
    height: 70px;
  }

  .timelineIcon span {
    font-size: 28px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    margin-right: 12px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }
}
